    var replacement=target&&Array.from(candidates).find(function(n){return visible(n)&&n.getClientRects().length&&(target.id?n.id===target.id:n.dataset.plAction===target.dataset.plAction&&n.dataset.plId===target.dataset.plId&&n.dataset.plKind===target.dataset.plKind&&n.dataset.plAccountId===target.dataset.plAccountId);});
